addEventListener('resize',()=>{drawTl();frame();tlFill.style.strokeDashoffset=done?0:1-clamp((t-P0) / (P1-P0),0,1);tlDots.forEach(c=>c.classList.toggle('is-in',cur-1>=+c.dataset.i));});
